
(()=>{
const root=document.getElementById('square-tape-player-v2'),canvas=root.querySelector('canvas'),ctx=canvas.getContext('2d'),audio=root.querySelector('.media-source'),fileInput=root.querySelector('.audio-file'),seek=root.querySelector('.playback-position'),mode=root.querySelector('.mode'),track=root.querySelector('.track'),clock=root.querySelector('.clock');
const photo=new Image();let ready=false,leftAngle=0,rightAngle=0,previous=0,loaded=false,objectURL=null,stopped=true,buffering=false,wind=0,windUntil=0,errorMessage='';
const hub=document.createElement('canvas');hub.width=310;hub.height=310;
function prepareHub(){const h=hub.getContext('2d');h.drawImage(photo,918,292,310,310,0,0,310,310);h.save();h.beginPath();h.moveTo(145,292);h.lineTo(168,292);h.lineTo(177,310);h.lineTo(135,310);h.closePath();h.clip();h.translate(155,155);h.rotate(Math.PI);h.drawImage(photo,918,292,310,310,-155,-155,310,310);h.restore()}
function driveSpindle(x,y,angle){
 ctx.save();ctx.translate(x,y);
 // The dark recessed drive sits inside the six teeth of the yellow hub.
 const well=ctx.createRadialGradient(-15,-20,4,0,0,74);well.addColorStop(0,'#22272a');well.addColorStop(.75,'#0b0e10');well.addColorStop(1,'#030506');
 ctx.beginPath();ctx.arc(0,0,64.5,0,Math.PI*2);ctx.fillStyle=well;ctx.fill();
 ctx.rotate(angle);
 const black=ctx.createLinearGradient(-50,-58,48,60);black.addColorStop(0,'#42484b');black.addColorStop(.24,'#202528');black.addColorStop(.65,'#111517');black.addColorStop(1,'#06090a');
 for(let i=0;i<6;i++){
  ctx.save();ctx.rotate(i*Math.PI/3+Math.PI/6);ctx.beginPath();ctx.roundRect(-10,-75,20,28,4);ctx.fillStyle=black;ctx.fill();ctx.beginPath();ctx.moveTo(-7,-70);ctx.lineTo(6,-70);ctx.strokeStyle='#667074';ctx.lineWidth=1.5;ctx.stroke();ctx.restore();
 }
 ctx.beginPath();ctx.arc(0,0,51,0,Math.PI*2);ctx.fillStyle=black;ctx.fill();ctx.strokeStyle='#40484c';ctx.lineWidth=2;ctx.stroke();
 for(let i=0;i<6;i++){
  ctx.save();ctx.rotate(i*Math.PI/3+Math.PI/6);ctx.beginPath();ctx.roundRect(-4,-44,8,21,3);ctx.fillStyle='#070b0d';ctx.fill();ctx.restore();
 }
 const boss=ctx.createRadialGradient(-9,-10,1,0,0,25);boss.addColorStop(0,'#4d5559');boss.addColorStop(.55,'#242b2f');boss.addColorStop(1,'#0b1013');ctx.beginPath();ctx.arc(0,0,25,0,Math.PI*2);ctx.fillStyle=boss;ctx.fill();ctx.strokeStyle='#080b0d';ctx.lineWidth=3;ctx.stroke();
 const axle=ctx.createLinearGradient(-8,-10,9,10);axle.addColorStop(0,'#acb5b6');axle.addColorStop(.45,'#535e63');axle.addColorStop(.75,'#adb8ba');axle.addColorStop(1,'#354046');ctx.beginPath();ctx.arc(0,0,10,0,Math.PI*2);ctx.fillStyle=axle;ctx.fill();ctx.beginPath();ctx.arc(0,0,3.5,0,Math.PI*2);ctx.fillStyle='#192126';ctx.fill();ctx.restore();
}
function writeTapeLabel(){
 const title=track.dataset.name||'My mixtape';
 ctx.save();ctx.beginPath();ctx.rect(205,130,1150,89);ctx.clip();ctx.fillStyle='#183e76';ctx.textAlign='left';ctx.textBaseline='middle';
 const family='"Caveat", "Bradley Hand", "Segoe Print", cursive';
 ctx.font='500 64px '+family;
 if(ctx.measureText(title).width<=1120){ctx.translate(218,178);ctx.rotate(-.008);ctx.fillText(title,0,0)}
 else{
  ctx.font='500 43px '+family;
  const words=title.split(/\s+/);let lines=[''];
  for(const word of words){const i=lines.length-1,candidate=(lines[i]+' '+word).trim();if(ctx.measureText(candidate).width>1120&&lines[i])lines.push(word);else lines[i]=candidate}
  let first=lines[0],second=lines.slice(1).join(' ');
  function fit(text){if(ctx.measureText(text).width<=1120)return text;while(text&&ctx.measureText(text+'…').width>1120)text=text.slice(0,-1);return text+'…'}
  ctx.fillText(fit(first),218,155);if(second)ctx.fillText(fit(second),218,198);
 }
 ctx.restore();
}
function draw(){
 if(!ready)return;ctx.setTransform(canvas.width/1487,0,0,canvas.height/963,0,0);ctx.clearRect(0,0,1487,963);ctx.save();ctx.translate(-25,-23);ctx.drawImage(photo,0,0);
 for(const[x,y,a]of[[463,447,leftAngle],[1073,447,rightAngle]]){
  ctx.save();ctx.translate(x,y);ctx.beginPath();ctx.arc(0,0,153,0,Math.PI*2);ctx.arc(0,0,65,0,Math.PI*2,true);ctx.clip();ctx.rotate(a);ctx.drawImage(hub,-155,-155);ctx.restore();driveSpindle(x,y,a);
 }
 ctx.save();ctx.beginPath();ctx.rect(57,482,293,135);ctx.moveTo(1077,585);ctx.lineTo(998,728);ctx.lineTo(1158,728);ctx.closePath();ctx.clip();ctx.drawImage(photo,0,0);ctx.restore();writeTapeLabel();ctx.restore();
}
function resize(){const d=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(canvas.clientWidth*d);canvas.height=Math.round(canvas.clientWidth*963/1487*d);draw()}
function playing(){return loaded&&!audio.paused&&!audio.ended&&!buffering}
function total(){return loaded&&Number.isFinite(audio.duration)?audio.duration:0}
function position(){return loaded?audio.currentTime:0}
function time(n){n=Math.floor(Math.max(0,Number.isFinite(n)?n:0));return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')}
function update(){const active=playing();root.querySelectorAll('.keys button').forEach(button=>{button.disabled=!loaded});mode.textContent=errorMessage?'ERROR':buffering?'WAIT':loaded?(active?'PLAY':stopped?'STOP':'PAUSE'):'IDLE';track.textContent=errorMessage||track.dataset.name||'Add tracks to begin';root.querySelector('[data-action=play]').setAttribute('aria-pressed',String(active));root.querySelector('[data-action=pause]').setAttribute('aria-pressed',String(!active&&!stopped));root.querySelector('[data-action=stop]').setAttribute('aria-pressed',String(stopped));canvas.setAttribute('aria-label','Cassette with rotating black drive spindles. Label: '+(track.dataset.name||'My mixtape'));updateTime();draw()}
function updateTime(){clock.textContent=time(position());seek.disabled=!loaded||!total();if(!dragging)seek.value=total()?String(position()/total()*1000):'0';seek.setAttribute('aria-valuetext',time(position())+' of '+time(total()))}
let dragging=false;
function setPosition(n){n=Math.min(total(),Math.max(0,n));if(loaded){if(Number.isFinite(audio.duration))audio.currentTime=n}updateTime()}
seek.addEventListener('input',()=>{dragging=true;setPosition(Number(seek.value)/1000*total())});seek.addEventListener('change',()=>{dragging=false;updateTime()});seek.addEventListener('blur',()=>{dragging=false});
async function play(){if(!loaded)return;const generation=trackGeneration;errorMessage='';stopped=false;if(loaded){try{await ensureAudioGraph();if(generation!==trackGeneration)return;await audio.play()}catch(e){if(generation!==trackGeneration)return;errorMessage='Playback unavailable — try another media file';buffering=false}}update()}
function pause(){if(loaded)audio.pause();buffering=false;stopped=false;update()}
function stop(){if(loaded)audio.pause();buffering=false;stopped=true;setPosition(0);windUntil=0;update()}
root.querySelector('.keys').addEventListener('click',e=>{const b=e.target.closest('button');if(!b||!loaded)return;switch(b.dataset.action){case'play':play();break;case'pause':pause();break;case'stop':stop();break;case'rewind':case'forward':{const d=b.dataset.action==='rewind'?-1:1;setPosition(position()+10*d);wind=d*9;windUntil=performance.now()+450;b.classList.add('flash');setTimeout(()=>b.classList.remove('flash'),450);break}}});
audio.addEventListener('loadedmetadata',update);audio.addEventListener('timeupdate',updateTime);audio.addEventListener('play',()=>{stopped=false;update()});audio.addEventListener('playing',()=>{buffering=false;update()});audio.addEventListener('pause',update);audio.addEventListener('waiting',()=>{buffering=true;update()});audio.addEventListener('error',()=>{if(loaded){errorMessage='Unsupported media codec — try MP3, AAC, or MP4';buffering=false;update()}});
const system=document.getElementById('tape-stereo-system'),queuePanel=document.getElementById('tape-playlist'),eqPanel=document.getElementById('tape-equalizer');
const queueList=queuePanel.querySelector('.queue-list'),queueEmpty=queuePanel.querySelector('.queue-empty');
let queue=[],queueIndex=-1,queuePage=0,queueSize=4,trackGeneration=0;
const eqFrequencies=[31.25,62.5,125,250,500,1000,2000,4000,8000,16000],eqLabels=['31','63','125','250','500','1k','2k','4k','8k','16k'];
let eqValues=Array(10).fill(0),eqEnabled=true,masterVolume=1;
const volumeInput=eqPanel.querySelector('.master-volume');
const savedEQ=window.signalStudioState?.widgetState?.privateContent;
if(Array.isArray(savedEQ?.eqValues)&&savedEQ.eqValues.length===10)eqValues=savedEQ.eqValues.map(v=>Number.isFinite(v)?Math.max(-12,Math.min(12,v)):0);
if(typeof savedEQ?.eqEnabled==='boolean')eqEnabled=savedEQ.eqEnabled;
if(Number.isFinite(savedEQ?.masterVolume))masterVolume=Math.max(0,Math.min(1,savedEQ.masterVolume));
function refreshVolume(){volumeInput.value=String(Math.round(masterVolume*100));volumeInput.setAttribute('aria-valuetext',volumeInput.value+' percent')}
function applyVolume(){if(audioGraph)audioGraph.masterGain.gain.setTargetAtTime(masterVolume,audioGraph.ac.currentTime,.025);else if(analysisUnavailable)audio.volume=masterVolume}
volumeInput.addEventListener('input',()=>{masterVolume=Number(volumeInput.value)/100;refreshVolume();applyVolume()});
volumeInput.addEventListener('change',saveEQ);
refreshVolume();
const faderGrid=eqPanel.querySelector('.fader-grid');
eqFrequencies.forEach((hz,i)=>{
 const band=document.createElement('label');band.className='eq-band';
 const name=document.createElement('span');name.textContent=eqLabels[i];
 const wrap=document.createElement('span');wrap.className='fader-wrap';const thumb=document.createElement('span');thumb.className='fader-thumb';thumb.setAttribute('aria-hidden','true');
 const input=document.createElement('input');input.type='range';input.min='-12';input.max='12';input.step='.5';input.value=String(eqValues[i]);input.dataset.band=String(i);input.setAttribute('aria-label',hz+' hertz gain');input.setAttribute('aria-orientation','vertical');
 const output=document.createElement('output');wrap.append(thumb,input);band.append(name,wrap,output);faderGrid.append(band);
 input.addEventListener('input',()=>changeEQ(i,Number(input.value),true));input.addEventListener('dblclick',()=>changeEQ(i,0,true));
});
function saveEQ(){window.signalStudioState?.setWidgetState?.({privateContent:{eqValues:[...eqValues],eqEnabled,masterVolume}})?.catch(()=>{})}
function refreshEQ(){
 Array.from(faderGrid.children).forEach((band,i)=>{band.querySelector('input').value=String(eqValues[i]);band.querySelector('.fader-thumb').style.setProperty('--position',String((12-eqValues[i])/24));band.querySelector('output').textContent=(eqValues[i]>0?'+':'')+String(eqValues[i]);band.querySelector('input').setAttribute('aria-valuetext',eqValues[i].toFixed(1)+' decibels')});
 eqPanel.classList.toggle('eq-bypassed',!eqEnabled);const toggle=eqPanel.querySelector('.eq-toggle');toggle.textContent=eqEnabled?'EQ ON':'BYPASS';toggle.setAttribute('aria-pressed',String(eqEnabled));
}
function applyEQ(){if(!audioGraph?.filters)return;const now=audioGraph.ac.currentTime;audioGraph.filters.forEach((filter,i)=>{filter.gain.setTargetAtTime(eqEnabled?eqValues[i]:0,now,.025)})}
function changeEQ(i,value,save){eqValues[i]=value;refreshEQ();applyEQ();if(save)saveEQ()}
eqPanel.querySelector('.eq-toggle').addEventListener('click',()=>{eqEnabled=!eqEnabled;refreshEQ();applyEQ();saveEQ()});eqPanel.querySelector('.eq-flat').addEventListener('click',()=>{eqValues.fill(0);refreshEQ();applyEQ();saveEQ()});
window.addEventListener('openai:set_globals',e=>{const s=e.detail?.globals?.widgetState?.privateContent;if(Number.isFinite(s?.masterVolume)){masterVolume=Math.max(0,Math.min(1,s.masterVolume));refreshVolume();applyVolume()}if(Array.isArray(s?.eqValues)&&s.eqValues.length===10){eqValues=s.eqValues.map(v=>Number.isFinite(v)?Math.max(-12,Math.min(12,v)):0);if(typeof s.eqEnabled==='boolean')eqEnabled=s.eqEnabled;refreshEQ();applyEQ()}});
function cleanTitle(file){return file.name.replace(/\.[^.]+$/,'').replace(/_+/g,' ').trim()||'Untitled track'}
function renderQueue(){
 const pages=Math.max(1,Math.ceil(queue.length/queueSize));queuePage=Math.min(queuePage,pages-1);queueList.replaceChildren();queueList.hidden=!queue.length;queueEmpty.hidden=!!queue.length;
 queuePanel.querySelector('.track-count').textContent=queue.length+' TRACK'+(queue.length===1?'':'S');
 queue.slice(queuePage*queueSize,(queuePage+1)*queueSize).forEach((file,offset)=>{
  const index=queuePage*queueSize+offset,row=document.createElement('button');row.type='button';row.className='queue-row';row.setAttribute('aria-current',String(index===queueIndex));row.setAttribute('aria-label','Play '+cleanTitle(file));row.setAttribute('data-tooltip',cleanTitle(file));
  const number=document.createElement('span');number.className='number';number.textContent=String(index+1).padStart(2,'0');const name=document.createElement('span');name.className='song';name.textContent=cleanTitle(file);const state=document.createElement('span');state.className='song-state';state.textContent=index===queueIndex?'●':'';row.append(number,name,state);row.addEventListener('click',()=>selectTrack(index,true));queueList.append(row);
 });
 queuePanel.querySelector('.queue-page').textContent=queue.length?(queuePage+1)+' / '+pages:'LOCAL MEDIA';queuePanel.querySelector('.page-prev').disabled=queuePage===0;queuePanel.querySelector('.page-next').disabled=queuePage>=pages-1;
}
function selectTrack(index,autoPlay=false){
 if(index<0||index>=queue.length)return;trackGeneration++;audio.pause();queueIndex=index;queuePage=Math.floor(index/queueSize);loaded=false;audio.removeAttribute('src');audio.load();if(objectURL?.startsWith('blob:'))URL.revokeObjectURL(objectURL);objectURL=queue[index].url||URL.createObjectURL(queue[index]);loaded=true;stopped=true;buffering=false;errorMessage='';track.dataset.name=cleanTitle(queue[index]);audio.src=objectURL;audio.load();update();renderQueue();if(autoPlay)play();
}
function addTracks(files){const incoming=Array.from(files).filter(file=>/^(audio|video)\//i.test(file.type||'')||/\.(mp3|wav|m4a|ogg|flac|aac|aif|aiff|opus|mp4|m4v|mov|webm|mkv|avi)$/i.test(file.name));if(!incoming.length)return;const first=queue.length;queue.push(...incoming);if(queueIndex<0)selectTrack(first);else renderQueue()}
const playlistStatus=queuePanel.querySelector('.playlist-status');
function playlistMessage(text){playlistStatus.textContent=text;playlistStatus.hidden=!text}
queuePanel.querySelector('.save-playlist').addEventListener('click',async()=>{
 try{const paths=queue.map(file=>file.path||window.signalStudioDesktop.filePath(file));const result=await window.signalStudioDesktop.savePlaylist(paths);if(!result.canceled)playlistMessage(result.error||'Saved '+result.name)}catch{playlistMessage('Unable to save this playlist. Add files from your computer first.')}
});
queuePanel.querySelector('.open-playlist').addEventListener('click',async()=>{
 const result=await window.signalStudioDesktop.openPlaylist();if(result.canceled)return;
 if(result.error){playlistMessage(result.error);return}
 if(!result.tracks?.length){playlistMessage('No available tracks. The files may have moved. Your current playlist is unchanged.');return}
 queue=result.tracks;queueIndex=-1;queuePage=0;selectTrack(0,false);
 playlistMessage(result.missing.length?'Opened '+result.name+' · '+result.missing.length+' missing track(s) skipped.':'Opened '+result.name);
});
fileInput.addEventListener('change',()=>{addTracks(fileInput.files);fileInput.value=''});
queuePanel.querySelector('.add-tracks').addEventListener('click',()=>fileInput.click());queuePanel.querySelector('.page-prev').addEventListener('click',()=>{queuePage--;renderQueue()});queuePanel.querySelector('.page-next').addEventListener('click',()=>{queuePage++;renderQueue()});
audio.addEventListener('ended',()=>{if(queueIndex+1<queue.length)selectTrack(queueIndex+1,true);else{stopped=true;buffering=false;update();renderQueue()}});
new ResizeObserver(()=>{const size=Math.max(1,Math.min(7,Math.floor((queuePanel.clientHeight-200)/48)));if(size!==queueSize){queueSize=size;queuePage=queueIndex>=0?Math.floor(queueIndex/queueSize):0;renderQueue()}}).observe(queuePanel);
refreshEQ();renderQueue();

const meterPanel=document.getElementById('tape-meter-panel'),meterSource=system.querySelector('.signal-source');
const meterViews=['.spectrum','.needles','.linear-vu','.waveform'].map(s=>{const c=system.querySelector(s);return {canvas:c,g:c.getContext('2d'),w:0,h:0}});
let audioGraph=null,analysisUnavailable=false,lastMeterTime=0;
const bandCount=32,bandValues=new Float32Array(bandCount),bandPeaks=new Float32Array(bandCount),vuPower=[0,0],peakLevel=[-60,-60],peakHold=[-60,-60],holdUntil=[0,0];
const clamp=(x,a,b)=>Math.max(a,Math.min(b,x));
function amplitudeDB(a){return a>0?20*Math.log10(a):-120}
async function ensureAudioGraph(){
 if(analysisUnavailable)return;
 if(!audioGraph){
  const AC=window.AudioContext||window.webkitAudioContext;if(!AC){analysisUnavailable=true;audio.volume=masterVolume;return}
  const ac=new AC();let source;
  try{
   source=ac.createMediaElementSource(audio);
   const stereo=ac.createGain();stereo.channelCount=2;stereo.channelCountMode='explicit';stereo.channelInterpretation='speakers';
   const splitter=ac.createChannelSplitter(2),silent=ac.createGain();silent.gain.value=0;
   const analysers=[ac.createAnalyser(),ac.createAnalyser()];
   const masterGain=ac.createGain();masterGain.gain.value=masterVolume;
   const filters=eqFrequencies.map((hz,i)=>{const f=ac.createBiquadFilter();f.type='peaking';f.frequency.value=hz;f.Q.value=1.4;f.gain.value=eqEnabled?eqValues[i]:0;return f});
   source.connect(masterGain);let tail=masterGain;for(const filter of filters){tail.connect(filter);tail=filter}tail.connect(stereo);stereo.connect(ac.destination);stereo.connect(splitter);
   analysers.forEach((a,i)=>{a.fftSize=4096;a.smoothingTimeConstant=.3;a.minDecibels=-90;a.maxDecibels=0;splitter.connect(a,i);a.connect(silent)});silent.connect(ac.destination);
   audioGraph={ac,source,masterGain,filters,stereo,splitter,silent,analysers,waves:analysers.map(a=>new Float32Array(a.fftSize)),spectra:analysers.map(a=>new Float32Array(a.frequencyBinCount))};
  }catch(e){if(source){source.disconnect();source.connect(ac.destination)}analysisUnavailable=true;audio.volume=masterVolume;try{await ac.resume()}catch(_){}return}
 }
 if(audioGraph.ac.state==='suspended')await audioGraph.ac.resume();
}
function resizeMeters(){for(const v of meterViews){v.w=v.canvas.clientWidth;v.h=v.canvas.clientHeight;const d=Math.min(devicePixelRatio||1,2);v.canvas.width=Math.round(v.w*d);v.canvas.height=Math.round(v.h*d);v.g.setTransform(d,0,0,d,0,0)}renderMeters(performance.now(),0)}
function meterText(g,s,x,y,color='#8dabb7',align='left'){g.font='11px ui-monospace,monospace';g.textAlign=align;g.textBaseline='middle';g.fillStyle=color;g.fillText(s,x,y)}
function drawSpectrum(v){
 const {g,w,h}=v;if(w<10||h<10)return;g.clearRect(0,0,w,h);
 const x=31,y=10,bottom=h-22,pw=w-x-12,ph=Math.max(10,bottom-y);
 for(const db of [-12,-48,-84]){const yy=y+((-12-db)/72)*ph;g.strokeStyle='#203038';g.lineWidth=.5;g.beginPath();g.moveTo(x,yy);g.lineTo(w-10,yy);g.stroke();meterText(g,String(db),25,yy,'#8a9aa2','right')}
 const step=pw/bandCount,picked=selectedBand();
 if(picked>=0){g.fillStyle='#f5ca7a12';g.fillRect(x+picked*step,y,step,ph);g.strokeStyle='#e6c37b70';g.lineWidth=1;g.beginPath();g.moveTo(x+(picked+.5)*step,y);g.lineTo(x+(picked+.5)*step,bottom);g.stroke();const level=bandValues[picked]<=-83.9?'below −84':bandValues[picked].toFixed(1);bandDetail.textContent=frequencyLabel(bandFrequency(picked))+' · '+level+' dB'}else bandDetail.textContent='';
 for(let i=0;i<bandCount;i++){
  const a=clamp((bandValues[i]+84)/72,0,1),xx=x+i*step+1,barH=a*ph;
  g.fillStyle=i===picked?'#ffd583':'#75dcf8';g.shadowColor=i===picked?'#ffd583':'#54d4ff';g.shadowBlur=a>0?6:0;
  for(let sy=0;sy<barH;sy+=4)g.fillRect(xx,bottom-sy-2,Math.max(1,step-2),3);
  g.shadowBlur=0;const p=clamp((bandPeaks[i]+84)/72,0,1);if(p>.015){g.fillStyle='#d0f6ff';g.fillRect(xx,bottom-p*ph,Math.max(1,step-2),2)}
 }
 for(const [f,label]of [[20,'20'],[100,'100'],[1000,'1k'],[5000,'5k'],[20000,'20k Hz']]){const px=x+Math.log(f/20)/Math.log(1000)*pw;meterText(g,label,px,h-9,'#8dabb7',f===20?'left':f===20000?'right':'center')}
}
function drawNeedles(v){
 const{g,w,h}=v;if(w<10||h<10)return;g.clearRect(0,0,w,h);
 const gap=6,gw=(w-gap-12)/2,gh=h-10;
 for(let ch=0;ch<2;ch++){
  const ox=6+ch*(gw+gap);g.save();g.translate(ox,5);g.beginPath();g.roundRect(0,0,gw,gh,4);g.clip();
  const light=g.createRadialGradient(gw*.5,gh*.65,1,gw*.5,gh*.65,gw*.75);light.addColorStop(0,'#1c2d36');light.addColorStop(.6,'#111c23');light.addColorStop(1,'#080e13');g.fillStyle=light;g.fillRect(0,0,gw,gh);
  const cx=gw*.5,cy=gh*.95,r=Math.min(gw*.47,gh*.79),start=-Math.PI*.83,end=-Math.PI*.17;
  const angle=db=>start+clamp((Math.pow(10,db/20)-.1)/(Math.pow(10,3/20)-.1),0,1)*(end-start);
  const point=(a,rad)=>[cx+Math.cos(a)*rad,cy+Math.sin(a)*rad];
  g.strokeStyle='#7895a4';g.lineWidth=2.2;g.beginPath();g.arc(cx,cy,r,start,end);g.stroke();g.strokeStyle='#f07868';g.lineWidth=4;g.beginPath();g.arc(cx,cy,r,angle(0),end);g.stroke();
  const ticks=gw<180?[-20,0,3]:[-20,-5,0,3];
  for(const db of ticks){const a=angle(db),p=point(a,r-6),q=point(a,r+1),t=point(a,r+12);g.strokeStyle=db>0?'#f07868':'#a5c4d1';g.lineWidth=2.2;g.beginPath();g.moveTo(...p);g.lineTo(...q);g.stroke();meterText(g,db>0?'+'+db:String(db),clamp(t[0],12,gw-12),Math.max(9,t[1]),db>0?'#f07868':'#b4d3df','center')}
  const vu=amplitudeDB(Math.sqrt(vuPower[ch]))+11,a=angle(vu),tip=point(a,r-3);
  g.shadowColor='#7ee4ff99';g.shadowBlur=5;g.shadowOffsetX=0;g.shadowOffsetY=0;g.strokeStyle='#a4efff';g.lineWidth=3;g.beginPath();g.moveTo(cx,cy);g.lineTo(...tip);g.stroke();g.shadowBlur=0;g.shadowOffsetX=0;g.shadowOffsetY=0;
  g.fillStyle='#526672';g.beginPath();g.arc(cx,cy,7,0,Math.PI*2);g.fill();meterText(g,ch?'R · VU':'L · VU',cx,gh*.65,'#8aabba','center');
  const sheen=g.createLinearGradient(0,0,0,gh);sheen.addColorStop(0,'#ffffff0b');sheen.addColorStop(.45,'#ffffff00');sheen.addColorStop(1,'#00000022');g.fillStyle=sheen;g.fillRect(0,0,gw,gh);g.restore();
 }
}
function drawLinear(v){
 const{g,w,h}=v;if(w<10||h<10)return;g.clearRect(0,0,w,h);const x=24,right=w-55,pw=right-x,segments=40,step=pw/segments,barH=Math.max(6,Math.min(15,h*.14));
 for(const db of [-60,-40,-20,-10,0])meterText(g,String(db),x+(db+60)/60*pw,12,'#90a4ad',db===0?'right':'center');
 for(let ch=0;ch<2;ch++){
  const yy=h*(ch?.68:.38),value=clamp((peakLevel[ch]+60)/60,0,1),hold=clamp((peakHold[ch]+60)/60,0,1);meterText(g,ch?'R':'L',9,yy,'#b1c7d0');
  for(let i=0;i<segments;i++){const db=-60+(i+1)/segments*60,color=db>=-3?'#ff6a57':db>=-12?'#ffd071':'#7ee7bb';g.globalAlpha=i/segments<value?1:.10;g.fillStyle=color;g.shadowColor=color;g.shadowBlur=i/segments<value?3:0;g.fillRect(x+i*step,yy-barH/2,Math.max(1,step-2),barH)}g.globalAlpha=1;g.shadowBlur=0;
  if(hold>0){g.fillStyle='#d8f8ef';g.fillRect(x+Math.min(segments-1,Math.floor(hold*segments))*step,yy-barH/2-2,Math.max(1,step-2),barH+4)}
  meterText(g,peakLevel[ch]<=-60?'≤−60':peakLevel[ch].toFixed(1),w-7,yy,'#a7dcd0','right');
 }
 meterText(g,'L / R',x,h-9,'#90a4ad');meterText(g,'1 s peak hold',w-8,h-9,'#90a4ad','right');
}
function drawWaveform(v){
 const {g,w,h}=v;if(w<10||h<10)return;g.clearRect(0,0,w,h);
 const live=playing()&&audioGraph&&!analysisUnavailable&&audioGraph.ac.state==='running';
 const left=30,right=w-13,plotWidth=right-left,laneHeight=(h-16)/2;
 for(let ch=0;ch<2;ch++){
  const top=8+ch*laneHeight,mid=top+laneHeight/2,amp=laneHeight*.35;
  for(const level of [-1,0,1]){const yy=mid-level*amp;g.strokeStyle=level===0?'#3a5964':'#20323c';g.lineWidth=level===0?1:.5;g.beginPath();g.moveTo(left,yy);g.lineTo(right,yy);g.stroke();}
  for(let step=1;step<4;step++){const xx=left+plotWidth*step/4;g.strokeStyle='#20323c';g.lineWidth=.5;g.beginPath();g.moveTo(xx,mid-amp);g.lineTo(xx,mid+amp);g.stroke()}
  const color=ch?'#9be5c4':'#85dfff';meterText(g,ch?'R':'L',9,mid,color);
  meterText(g,'+1',left-5,mid-amp,'#78949f','right');meterText(g,'−1',left-5,mid+amp,'#78949f','right');
  g.strokeStyle=color;g.lineWidth=1.4;g.shadowColor=color;g.shadowBlur=3;g.beginPath();
  if(live){
   const samples=audioGraph.waves[ch],count=Math.min(samples.length,Math.round(audioGraph.ac.sampleRate*.020));let start=0;
   // Align on a rising zero crossing to keep periodic signals readable.
   const search=Math.min(samples.length-count,Math.floor(count/2));for(let i=1;i<search;i++){if(samples[i-1]<=0&&samples[i]>0){start=i;break}}
   const pixels=Math.max(1,Math.floor(plotWidth));
   for(let px=0;px<pixels;px++){
    const from=start+Math.floor(px*count/pixels),to=Math.min(start+count,Math.max(from+1,start+Math.floor((px+1)*count/pixels)));let low=1,high=-1;
    for(let j=from;j<to;j++){low=Math.min(low,samples[j]);high=Math.max(high,samples[j])}
    const x=left+px;g.moveTo(x,mid-clamp(high,-1,1)*amp);g.lineTo(x,mid-clamp(low,-1,1)*amp);
   }
  }else{g.moveTo(left,mid);g.lineTo(right,mid)}
  g.stroke();g.shadowBlur=0;
  meterText(g,'0',left,top+laneHeight-5,'#78949f');meterText(g,'20 ms',right,top+laneHeight-5,'#78949f','right');
 }
}

function renderMeters(t,dt){
 const active=playing(),signal=[{rms:0,peak:0},{rms:0,peak:0}],targetBands=new Float32Array(bandCount).fill(-84);
 let label=loaded?(analysisUnavailable?'UNAVAILABLE':active?'LIVE':'IDLE'):'IDLE';
 if(active&&loaded&&audioGraph&&!analysisUnavailable&&audioGraph.ac.state==='running'){
  audioGraph.analysers.forEach((a,ch)=>{a.getFloatTimeDomainData(audioGraph.waves[ch]);a.getFloatFrequencyData(audioGraph.spectra[ch]);let sum=0,peak=0;for(const sample of audioGraph.waves[ch]){sum+=sample*sample;peak=Math.max(peak,Math.abs(sample))}signal[ch]={rms:Math.sqrt(sum/audioGraph.waves[ch].length),peak}});
  const binHz=audioGraph.ac.sampleRate/4096,nyquist=audioGraph.ac.sampleRate/2;
  for(let i=0;i<bandCount;i++){const f0=20*Math.pow(1000,i/bandCount),f1=Math.min(nyquist,20*Math.pow(1000,(i+1)/bandCount));if(f0>=nyquist)continue;const lo=clamp(Math.floor(f0/binHz),1,2047),hi=clamp(Math.ceil(f1/binHz),lo+1,2048);let power=0;for(let j=lo;j<hi;j++)power+=(Math.pow(10,audioGraph.spectra[0][j]/10)+Math.pow(10,audioGraph.spectra[1][j]/10))/2;targetBands[i]=Math.max(-84,10*Math.log10(Math.max(1e-12,power/(hi-lo))))}
 }
 if(meterSource.textContent!==label)meterSource.textContent=label;

 for(let i=0;i<bandCount;i++){const k=1-Math.exp(-Math.max(0,dt)/(targetBands[i]>bandValues[i]?.022:.10));bandValues[i]+=(targetBands[i]-bandValues[i])*k;bandPeaks[i]=Math.max(bandValues[i],bandPeaks[i]-dt*18)}
 for(let ch=0;ch<2;ch++){const vuK=1-Math.exp(-Math.max(0,dt)/(signal[ch].rms**2>vuPower[ch]?.045:.18));vuPower[ch]+=(signal[ch].rms**2-vuPower[ch])*vuK;const db=Math.max(-60,amplitudeDB(signal[ch].peak));peakLevel[ch]=Math.max(db,peakLevel[ch]-dt*32);if(db>=peakHold[ch]){peakHold[ch]=db;holdUntil[ch]=t+1000}else if(t>holdUntil[ch])peakHold[ch]=Math.max(db,peakHold[ch]-dt*24)}
 drawSpectrum(meterViews[0]);drawNeedles(meterViews[1]);drawLinear(meterViews[2]);drawWaveform(meterViews[3]);
}
bandValues.fill(-84);bandPeaks.fill(-84);
const spectrumPicker=system.querySelector('.spectrum-picker'),bandDetail=system.querySelector('.band-detail');
let hoveredBand=-1,pinnedBand=-1;
function selectedBand(){return hoveredBand>=0?hoveredBand:pinnedBand}
function bandFrequency(index){return 20*Math.pow(1000,(index+.5)/bandCount)}
function frequencyLabel(hz){return hz>=1000?(hz/1000).toFixed(hz>=10000?1:2)+' kHz':Math.round(hz)+' Hz'}
function inspectBand(index,pin=false){index=clamp(Math.round(index),0,bandCount-1);hoveredBand=index;if(pin)pinnedBand=index;spectrumPicker.value=String(index);spectrumPicker.setAttribute('aria-valuetext',frequencyLabel(bandFrequency(index))+', '+(bandValues[index]<=-83.9?'below display floor':bandValues[index].toFixed(1)+' decibels'));drawSpectrum(meterViews[0])}
spectrumPicker.addEventListener('pointermove',e=>{if(e.pointerType==='touch')return;const box=spectrumPicker.getBoundingClientRect();inspectBand((e.clientX-box.left)/box.width*(bandCount-1))});
spectrumPicker.addEventListener('pointerleave',()=>{hoveredBand=-1;drawSpectrum(meterViews[0])});
spectrumPicker.addEventListener('input',()=>inspectBand(Number(spectrumPicker.value),true));
spectrumPicker.addEventListener('focus',()=>inspectBand(Number(spectrumPicker.value)));
spectrumPicker.addEventListener('blur',()=>{hoveredBand=-1;drawSpectrum(meterViews[0])});
spectrumPicker.addEventListener('keydown',e=>{if(e.key==='Escape'){pinnedBand=-1;hoveredBand=-1;spectrumPicker.blur();drawSpectrum(meterViews[0])}});


let lastDisplay=0;
function animate(t){if(t-lastMeterTime>=33){renderMeters(t,lastMeterTime?Math.min((t-lastMeterTime)/1000,.1):.033);lastMeterTime=t}const dt=previous?Math.min((t-previous)/1000,.05):0;previous=t;const active=playing(),speed=t<windUntil?wind:active?1:0;if(speed&&ready){leftAngle+=dt*1.05*speed;rightAngle+=dt*.76*speed;draw()}if(t-lastDisplay>200){updateTime();lastDisplay=t}requestAnimationFrame(animate)}
photo.onload=()=>{ready=true;prepareHub();resize()};photo.onerror=()=>{errorMessage='Cassette image could not load';update()};photo.src='data:image/jpeg;base64,';new ResizeObserver(()=>requestAnimationFrame(resize)).observe(canvas);const meterResize=new ResizeObserver(()=>requestAnimationFrame(resizeMeters));meterViews.forEach(v=>meterResize.observe(v.canvas));resizeMeters();if(document.fonts){document.fonts.load('500 64px Caveat').then(()=>draw()).catch(()=>{});document.fonts.ready.then(()=>draw())}update();requestAnimationFrame(animate);
})();


(()=>{
 const viewport=document.getElementById('cassette-rack-scroll'),rack=document.getElementById('tape-stereo-system');
 let frame=0;
 function layout(){
  frame=0;const body=getComputedStyle(document.body),rawWidth=document.documentElement.clientWidth-parseFloat(body.paddingLeft)-parseFloat(body.paddingRight);
  const maximized=document.documentElement.dataset.maximized==='true',fit=rawWidth>=1000||maximized;
  const actualAvailable=Math.max(1,document.documentElement.clientHeight-viewport.offsetTop-parseFloat(body.paddingBottom)-2);
  const scale=fit?Math.min(1,rawWidth/1000,actualAvailable/540):1;
  viewport.style.zoom=String(scale);viewport.style.width=scale<1?(rawWidth/scale)+'px':'100%';
  const width=rawWidth/scale,columns=fit?3:width>=680?2:1,available=actualAvailable/scale;
  const panel=fit?Math.max(180,Math.min((width-2)/3,available-250)):Math.max(320,Math.min((width-2)/columns,520));
  const lower=fit?available-panel:340;
  document.documentElement.dataset.fit=String(fit);rack.dataset.columns=String(columns);
  rack.style.setProperty('--panel-size',panel+'px');rack.style.setProperty('--lower-size',lower+'px');

 }
 function schedule(){if(!frame)frame=requestAnimationFrame(layout)}
 new ResizeObserver(schedule).observe(viewport);window.addEventListener('resize',schedule);layout();
})();
(()=>{
 const buttons=[...document.querySelectorAll('[data-sound-info]'),document.querySelector('.studio-about-link')];
 buttons.forEach(button=>button.addEventListener('click',()=>{
  const topic=button.dataset.soundInfo||'about',box=button.getBoundingClientRect();
  window.signalStudioDesktop.openGuide(topic,{x:box.x,y:box.y,width:box.width,height:box.height});
 }));
})();
if(window.lucide)window.lucide.createIcons();
